-- Constraints
ALTER TABLE "clinico"."alergia_paciente_grupo" ADD CONSTRAINT "alergia_paciente_grupo_pkey" PRIMARY KEY (id);
ALTER TABLE "clinico"."alergia_paciente_grupo" ADD CONSTRAINT "alergia_paciente_grupo_id_paciente_id_grupo_alimentario_key" UNIQUE (id_paciente, id_grupo_alimentario);
ALTER TABLE "clinico"."alergia_paciente_grupo" ADD CONSTRAINT "alergia_paciente_grupo_id_paciente_fkey" FOREIGN KEY (id_paciente) REFERENCES usuarios.paciente(id);
ALTER TABLE "clinico"."alergia_paciente_grupo" ADD CONSTRAINT "alergia_paciente_grupo_id_grupo_alimentario_fkey" FOREIGN KEY (id_grupo_alimentario) REFERENCES nutricion.grupo_alimentario(id);
ALTER TABLE "clinico"."alergia_paciente_ingrediente" ADD CONSTRAINT "alergia_paciente_ingrediente_pkey" PRIMARY KEY (id);
ALTER TABLE "clinico"."alergia_paciente_ingrediente" ADD CONSTRAINT "alergia_paciente_ingrediente_id_paciente_id_ingrediente_key" UNIQUE (id_paciente, id_ingrediente);
ALTER TABLE "clinico"."alergia_paciente_ingrediente" ADD CONSTRAINT "alergia_paciente_ingrediente_id_paciente_fkey" FOREIGN KEY (id_paciente) REFERENCES usuarios.paciente(id);
ALTER TABLE "clinico"."alergia_paciente_ingrediente" ADD CONSTRAINT "alergia_paciente_ingrediente_id_ingrediente_fkey" FOREIGN KEY (id_ingrediente) REFERENCES nutricion.ingrediente(id);
ALTER TABLE "clinico"."control_condicion_activa" ADD CONSTRAINT "control_condicion_activa_pkey" PRIMARY KEY (id);
ALTER TABLE "clinico"."control_condicion_activa" ADD CONSTRAINT "control_condicion_activa_id_control_id_condicion_key" UNIQUE (id_control, id_condicion);
ALTER TABLE "clinico"."control_condicion_activa" ADD CONSTRAINT "control_condicion_activa_id_control_fkey" FOREIGN KEY (id_control) REFERENCES clinico.control_paciente(id) ON DELETE CASCADE;
ALTER TABLE "clinico"."control_condicion_activa" ADD CONSTRAINT "control_condicion_activa_id_condicion_fkey" FOREIGN KEY (id_condicion) REFERENCES heuristico.condicion(id);
ALTER TABLE "clinico"."control_paciente" ADD CONSTRAINT "control_paciente_pkey" PRIMARY KEY (id);
ALTER TABLE "clinico"."control_paciente" ADD CONSTRAINT "control_paciente_id_paciente_fkey" FOREIGN KEY (id_paciente) REFERENCES usuarios.paciente(id);
ALTER TABLE "clinico"."control_paciente" ADD CONSTRAINT "control_paciente_id_condicion_nutricional_resultado_fkey" FOREIGN KEY (id_condicion_nutricional_resultado) REFERENCES heuristico.condicion(id);
ALTER TABLE "clinico"."diagnostico_paciente" ADD CONSTRAINT "diagnostico_paciente_pkey" PRIMARY KEY (id);
ALTER TABLE "clinico"."diagnostico_paciente" ADD CONSTRAINT "diagnostico_paciente_id_paciente_id_condicion_fecha_diagnos_key" UNIQUE (id_paciente, id_condicion, fecha_diagnostico);
ALTER TABLE "clinico"."diagnostico_paciente" ADD CONSTRAINT "diagnostico_paciente_id_paciente_fkey" FOREIGN KEY (id_paciente) REFERENCES usuarios.paciente(id);
